34	export function useActivityFeed(
35	  teamId: string | null,
36	  filter: string = "All",
37	  actorId: string | null = null
38	) {
39	  const queryClient = useQueryClient();
40	  const actions = getActionsForFilter(filter);
41	  const queryKey = ["activity-feed", teamId, filter, actorId];
42	
43	  // Cursor for pagination (oldest created_at in current set)
44	  const [before, setBefore] = useState<string | null>(null);
45	  const [hasMore, setHasMore] = useState(false);
46	
47	  // Accumulate pages locally so "Load more" appends
48	  const [allActivities, setAllActivities] = useState<ActivityItem[]>([]);
49	  const initialLoaded = useRef(false);
50	
51	  const { data, isLoading, isFetching, error } = useQuery<ActivityItem[]>({
52	    queryKey: [...queryKey, before],
53	    queryFn: async () => {
54	      if (!teamId) return [];
55	
56	      let q = (supabase as any)
57	        .from("activity_log")
58	        .select("*")
59	        .eq("team_id", teamId)
60	        .order("created_at", { ascending: false })
61	        .limit(PAGE_SIZE + 1); // +1 to detect hasMore
62	
63	      if (actions && actions.length > 0) {
64	        q = q.in("action", actions);
65	      }
66	      if (actorId) {
67	        q = q.eq("actor_id", actorId);
68	      }
69	      if (before) {
70	        q = q.lt("created_at", before);
71	      }
72	
73	      const { data: rows, error } = await q;
74	      if (error) throw error;
75	      return (rows ?? []) as ActivityItem[];
76	    },
77	    enabled: !!teamId,
78	    staleTime: 30_000,
79	  });
80	
81	  // Merge pages when data arrives
82	  useEffect(() => {
83	    if (!data) return;
84	
85	    const more = data.length > PAGE_SIZE;
86	    const page = more ? data.slice(0, PAGE_SIZE) : data;
87	    setHasMore(more);
88	
89	    if (!before) {
90	      // First page — reset
91	      setAllActivities(page);
92	      initialLoaded.current = true;
93	    } else {
94	      // Subsequent page — append
95	      setAllActivities((prev) => {
96	        const existingIds = new Set(prev.map((a) => a.id));
97	        const fresh = page.filter((a) => !existingIds.has(a.id));
98	        return [...prev, ...fresh];
99	      });
100	    }
101	  }, [data]);
102	
103	  // Reset when teamId, filter, or actorId changes
104	  useEffect(() => {
105	    setBefore(null);
106	    setAllActivities([]);
107	    initialLoaded.current = false;
108	  }, [teamId, filter, actorId]);
109	
110	  // Realtime subscription — invalidate first-page query on new inserts
111	  useEffect(() => {
112	    if (!teamId) return;
113	
114	    const channel = supabase
115	      .channel(`activity-log-${teamId}`)
116	      .on(
117	        "postgres_changes",
118	        {
119	          event: "INSERT",
120	          schema: "public",
121	          table: "activity_log",
122	          filter: `team_id=eq.${teamId}`,
123	        },
124	        (payload) => {
125	          const newItem = payload.new as ActivityItem;
126	          // If filtering by a specific actor, skip items from other actors
127	          if (actorId && newItem.actor_id !== actorId) return;
128	          // Prepend to the displayed list immediately (optimistic)
129	          setAllActivities((prev) => {
130	            if (prev.some((a) => a.id === newItem.id)) return prev;
131	            return [newItem, ...prev];
132	          });
133	          // Also invalidate so first-page re-fetches on next stale check
134	          queryClient.invalidateQueries({ queryKey: ["activity-feed", teamId, filter, actorId] });
135	        }
136	      )
137	      .subscribe();
138	
139	    return () => {
140	      supabase.removeChannel(channel);
141	    };
142	  }, [teamId, filter, actorId, queryClient]);
143	
144	  function loadMore() {
145	    if (!hasMore || isFetching) return;
146	    const last = allActivities[allActivities.length - 1];
147	    if (last) setBefore(last.created_at);
148	  }
149	
150	  return {
151	    activities: allActivities,
152	    isLoading: isLoading && allActivities.length === 0,
153	    isFetching,
154	    hasMore,
155	    loadMore,
156	    error,
157	  };
158	}
